import { ENTITIES } from '@/lib/data/entities';
import { DEFAULT_PERMISSIONS, type Role } from '@/lib/rbac';
import { AUTOMATION_EVENTS } from '@/lib/automation';

const q = (s: string | null | undefined) => (s === null || s === undefined ? 'null' : `'${s.replace(/'/g, "''")}'`);
const arr = (a: string[] | null | undefined) => (a ? `array[${a.map(q).join(',')}]::text[]` : 'null');

/** Builds supabase/migrations/20261113000350_config.sql from the TypeScript registry. */
export function buildConfigSql(): string {
  const out: string[] = [
    '-- GENERATED by scripts/gen-sql-config.ts from src/lib/data/entities.ts, src/lib/rbac.ts and src/lib/automation.ts.',
    '-- Do not edit by hand: run `npm run gen:sql`. A test fails if this file is stale.',
    '',
    'delete from public.status_transitions;',
    'delete from public.entity_rules;',
    'delete from public.role_permissions where company_id is null;',
    'delete from public.automation_events;',
    '',
  ];
  for (const def of Object.values(ENTITIES)) {
    if (!def) continue;
    const statusIsField = def.fields.some((f) => f.key === 'status');
    const hasTransitions = !!def.statuses && !statusIsField;
    const protectedCols = def.fields.filter((f) => f.form === false || f.readOnly).map((f) => f.key);
    out.push(
      `insert into public.entity_rules (table_name, module, number_prefix, initial_status, has_transitions, editable_in, deletable_in, immutable, amount_col, protected_cols) values (${[
        q(def.table), q(def.module), q(def.numberPrefix ?? null), q(hasTransitions ? def.initialStatus ?? null : null), String(hasTransitions),
        arr(def.editableIn ?? null), arr(def.deletableIn ?? null), String(!!def.immutable),
        q(def.amountKey ?? null), arr(protectedCols),
      ].join(', ')});`,
    );
  }
  out.push('');
  const seen = new Set<string>();
  for (const def of Object.values(ENTITIES)) {
    for (const t of def?.transitions ?? []) {
      for (const from of t.from) {
        const key = `${def!.table}:${from}:${t.to}`;
        if (seen.has(key)) throw new Error(`Duplicate transition ${key}`);
        seen.add(key);
        out.push(`insert into public.status_transitions (table_name, from_status, to_status, action, require_comment) values (${q(def!.table)}, ${q(from)}, ${q(t.to)}, ${q(t.action)}, ${!!t.requireComment});`);
      }
    }
  }
  out.push('');
  for (const [role, matrix] of Object.entries(DEFAULT_PERMISSIONS) as [Role, Record<string, string[]>][]) {
    for (const [module, actions] of Object.entries(matrix)) {
      out.push(`insert into public.role_permissions (company_id, role, module, actions) values (null, ${q(role)}, ${q(module)}, ${arr(actions)});`);
    }
  }
  out.push('');
  for (const e of AUTOMATION_EVENTS) {
    out.push(`insert into public.automation_events (id, label, roles, trigger_kind) values (${q(e.id)}, ${q(e.label)}, ${arr(e.roles)}, ${q(e.trigger)});`);
  }
  return `${out.join('\n')}\n`;
}
